/**
 * A visualization is a PURE function of (algorithm, input) -> an ordered list of steps (ADR-009, VIZ-002).
 * Nothing here is random, time dependent or generated by a model: the same input always yields the same trace, and
 * every trace is checked by unit tests against an independent reference implementation.
 */
export type Mark = "none" | "active" | "compare" | "swap" | "sorted" | "found" | "window" | "dim";

/** `value` is null for a cell that has not been computed yet (a DP table before it is filled). */
export type Cell = { value: number | null; mark: Mark };

export type ArrayFrame = {
  kind: "array";
  cells: Cell[];
  pointers: { label: string; index: number }[];
  /** Small labelled numbers shown next to the array (a running sum, the best so far ...). */
  stats: { label: string; value: string }[];
  /** An optional second row (the merge buffer, a DP table ...). */
  buffer?: { label: string; cells: Cell[] };
};

export type StackFrame = {
  kind: "stack";
  chars: string[];
  at: number;
  stack: string[];
  verdict?: "balanced" | "unbalanced";
};

export type NodeState = "unseen" | "queued" | "visiting" | "done";

export type GraphFrame = {
  kind: "graph";
  nodes: { id: number; state: NodeState }[];
  edges: [number, number][];
  queue: number[];
  order: number[];
};

export type Frame = ArrayFrame | StackFrame | GraphFrame;

/** `line` is the index of the highlighted pseudocode line for this step. */
export type Step = { frame: Frame; note: string; line: number };

export type Trace = { algorithm: string; pseudo: string[]; steps: Step[] };

export type CatalogEntry = {
  id: string;
  title: string;
  summary: string;
  inputLabel: string;
  inputPattern: string;
  defaultInput: string;
  paramLabel: string | null;
  paramPattern: string | null;
  defaultParam: string;
};

/** A hard ceiling so no input can make the browser build an enormous trace. */
export const MAX_STEPS = 3000;

export class VizInputError extends Error {}
